---- DOMAIN
// Domain vocabulary for the Hero Ops Console. The const arrays are the single
// source for both the TypeScript unions and any select options built from them.

export const POWER_CLASSES = ['Aerial', 'Energy', 'Psionic', 'Tech', 'Mutant', 'Cosmic', 'Enhanced'] as const;
export type PowerClass = (typeof POWER_CLASSES)[number];

export const HERO_STATUSES = ['Active', 'Injured', 'Reserve', 'MIA'] as const;
export type HeroStatus = (typeof HERO_STATUSES)[number];

export const CLEARANCE_TIERS = ['Tier 1', 'Tier 2', 'Tier 3', 'Tier 4', 'Tier 5'] as const;
export type ClearanceTier = (typeof CLEARANCE_TIERS)[number];

export interface Hero {
  readonly id: string;
  readonly name: string;
  readonly alias: string;
  readonly powerClass: PowerClass;
  /** Power index on a 0-100 scale. */
  readonly powerIndex: number;
  readonly status: HeroStatus;
  readonly clearance: ClearanceTier;
  readonly missionCount: number;
  /** Mission success rate as a percentage, 0-100. */
  readonly successRate: number;
  readonly notes: string;
}

/**
 * The fields a dossier edit may change. Clearance and the mission figures are
 * owned by the mission record, not the dossier, so they are not editable here.
 */
export type HeroEdit = Pick<Hero, 'name' | 'alias' | 'powerClass' | 'powerIndex' | 'status' | 'notes'>;
import { Service, computed, signal } from '@angular/core';
import type { Signal } from '@angular/core';
import { EXAMPLE_ROSTER } from './example-roster';
import type { Hero, HeroEdit } from './hero.model';

/**
 * In-memory hero store. There is no backend: the roster is seeded from
 * EXAMPLE_ROSTER, which is example data, and every change lives only until the
 * page reloads.
 */
@Service()
export class HeroService {
  private readonly heroes = signal<readonly Hero[]>(EXAMPLE_ROSTER);

  readonly roster = this.heroes.asReadonly();

  /** A live lookup. Resolves to undefined when no hero has that id. */
  find(id: string): Signal<Hero | undefined> {
    return computed(() => this.heroes().find((hero) => hero.id === id));
  }

  /** Applies a dossier edit to one hero. An unknown id leaves the roster unchanged. */
  update(id: string, changes: Partial<HeroEdit>): void {
    this.heroes.update((list) => list.map((hero) => (hero.id === id ? { ...hero, ...changes } : hero)));
  }
}
import type { Hero } from './hero.model';

/**
 * EXAMPLE DATA. These heroes are invented for the Hero Ops Console capstone and
 * are not real records. They are the roster from the build spec, with the power
 * classes, status, clearance tiers, and mission figures the console displays.
 */
export const EXAMPLE_ROSTER: readonly Hero[] = [
  { id: 'HRO-0007', name: 'Silverwing', alias: 'Ada Voss', powerClass: 'Aerial', powerIndex: 88, status: 'Active', clearance: 'Tier 4', missionCount: 64, successRate: 92, notes: 'Precision flyer. Excels at extraction and high-altitude recon. Pairs well with ground-anchor heroes on breach ops.' },
  { id: 'HRO-0012', name: 'Dr. Ion', alias: 'Marcus Reyes', powerClass: 'Energy', powerIndex: 94, status: 'Active', clearance: 'Tier 5', missionCount: 118, successRate: 88, notes: 'Directed-energy specialist. High output, needs a cooldown window between deployments.' },
  { id: 'HRO-0021', name: 'Vantablack', alias: 'Unknown', powerClass: 'Psionic', powerIndex: 81, status: 'Reserve', clearance: 'Tier 3', missionCount: 29, successRate: 79, notes: 'Stealth and misdirection. Prefers solo infiltration; low profile by design.' },
  { id: 'HRO-0033', name: 'Aurora Vale', alias: 'Lena Park', powerClass: 'Cosmic', powerIndex: 97, status: 'Active', clearance: 'Tier 5', missionCount: 151, successRate: 90, notes: 'Cosmic-tier heavy hitter. Reserved for tier-4 and tier-5 threat responses only.' },
  { id: 'HRO-0040', name: 'Magnetar', alias: 'Idris Kane', powerClass: 'Enhanced', powerIndex: 76, status: 'Injured', clearance: 'Tier 3', missionCount: 57, successRate: 84, notes: 'Magnetic-field control. Currently on medical hold after Harbor Breach.' },
  { id: 'HRO-0044', name: 'The Tinkerer', alias: 'Sam Okafor', powerClass: 'Tech', powerIndex: 69, status: 'Active', clearance: 'Tier 2', missionCount: 22, successRate: 95, notes: 'Gadget and drone support. Force multiplier on any team; rarely deployed alone.' },
  { id: 'HRO-0051', name: 'Halcyon', alias: 'Priya Nair', powerClass: 'Psionic', powerIndex: 85, status: 'Active', clearance: 'Tier 4', missionCount: 73, successRate: 87, notes: 'Crowd-calming empath. De-escalation specialist for civilian-dense operations.' },
  { id: 'HRO-0058', name: 'Rift', alias: 'Classified', powerClass: 'Cosmic', powerIndex: 91, status: 'Reserve', clearance: 'Tier 4', missionCount: 44, successRate: 82, notes: 'Short-range teleport. Powerful but unstable; flagged for supervised deployment.' },
  { id: 'HRO-0063', name: 'Ember Cho', alias: 'Jae Cho', powerClass: 'Energy', powerIndex: 78, status: 'Active', clearance: 'Tier 3', missionCount: 48, successRate: 86, notes: 'Thermal projection. Strong area control, watch collateral on urban ops.' },
  { id: 'HRO-0070', name: 'Null', alias: 'Unknown', powerClass: 'Mutant', powerIndex: 83, status: 'MIA', clearance: 'Tier 4', missionCount: 66, successRate: 80, notes: 'Power-nullification field. Last seen during Operation Nightfall; status unresolved.' },
  { id: 'HRO-0075', name: 'Grond', alias: 'Boris Volkov', powerClass: 'Enhanced', powerIndex: 72, status: 'Active', clearance: 'Tier 2', missionCount: 31, successRate: 90, notes: 'Raw strength and durability. The wall the rest of the team stands behind.' },
  { id: 'HRO-0081', name: 'Ms. Meridian', alias: 'Grace Bello', powerClass: 'Tech', powerIndex: 80, status: 'Active', clearance: 'Tier 3', missionCount: 59, successRate: 89, notes: 'Tactical AI handler. Coordinates multi-hero ops from the field.' },
];
---- DASH
import { Component, inject } from '@angular/core';
import { RouterLink } from '@angular/router';
import { NgIcon, provideIcons } from '@ng-icons/core';
import { lucideActivity, lucideShieldAlert, lucideUserCheck, lucideUserPlus, lucideZap } from '@ng-icons/lucide';
import { HlmBadgeImports } from '@spartan-ng/helm/badge';
import { HlmButtonImports } from '@spartan-ng/helm/button';
import { HeroCard } from '../ui/hero-card/hero-card';
import { StatTile } from '../ui/stat-tile/stat-tile';
import { DashboardViewModel } from './dashboard.view-model';

@Component({
  selector: 'app-dashboard',
  imports: [RouterLink, NgIcon, HlmBadgeImports, HlmButtonImports, HeroCard, StatTile],
  providers: [
    DashboardViewModel,
    provideIcons({ lucideActivity, lucideShieldAlert, lucideUserCheck, lucideUserPlus, lucideZap }),
  ],
  templateUrl: './dashboard.html',
  styleUrl: './dashboard.css',
})
export class Dashboard {
  protected readonly vm = inject(DashboardViewModel);
}
import { computed, inject, Injectable } from '@angular/core';
import { HeroService } from '../domain/hero.service';
import type { Hero } from '../domain/hero.model';

export interface DashboardStat {
  readonly label: string;
  readonly value: string;
  readonly detail: string;
  readonly icon: string;
}

const TOP_HERO_COUNT = 4;

function mean(values: readonly number[]): number {
  return values.length ? Math.round(values.reduce((sum, value) => sum + value, 0) / values.length) : 0;
}

/** Component-scoped: the dashboard provides it, so each visit starts a fresh view of the roster. */
@Injectable()
export class DashboardViewModel {
  private readonly heroes = inject(HeroService);
  private readonly roster = this.heroes.roster;

  readonly rosterCount = computed(() => this.roster().length);

  /** The strongest heroes by power index. A copy is sorted, so the roster signal is never mutated. */
  readonly topHeroes = computed<readonly Hero[]>(() =>
    [...this.roster()].sort((a, b) => b.powerIndex - a.powerIndex).slice(0, TOP_HERO_COUNT),
  );

  readonly stats = computed<readonly DashboardStat[]>(() => {
    const roster = this.roster();
    const active = roster.filter((hero) => hero.status === 'Active').length;
    const alerts = roster.filter((hero) => hero.status === 'Injured' || hero.status === 'MIA').length;
    const missions = roster.reduce((sum, hero) => sum + hero.missionCount, 0);

    return [
      { label: 'Heroes on roster', value: String(roster.length), detail: `${active} active`, icon: 'lucideUserCheck' },
      {
        label: 'Missions on record',
        value: String(missions),
        detail: `${mean(roster.map((hero) => hero.successRate))}% average success`,
        icon: 'lucideActivity',
      },
      {
        label: 'Average power',
        value: String(mean(roster.map((hero) => hero.powerIndex))),
        detail: 'Power index, out of 100',
        icon: 'lucideZap',
      },
      { label: 'Status alerts', value: String(alerts), detail: 'Injured or MIA', icon: 'lucideShieldAlert' },
    ];
  });
}
